//! Repo sources for the in-browser edition.
//!
//! - [`open_directory_snapshot`]: the user picks a local folder via the
//!   File System Access API; a small JS walker (written here as a string,
//!   evaluated once) snapshots every file's bytes into a map, which the
//!   app turns into a `MemoryFs` for the engine. The async boundary
//!   (JS Promises, the directory-handle AsyncIterator) stays on the JS
//!   side of the fence; the engine remains synchronous.
//! - [`demo_snapshot`]: the embedded demo repo (same file-map shape),
//!   generated by `tools/make_demo.py`, so the browser UI works in
//!   browsers without the File System Access API.

use std::collections::BTreeMap;

use js_sys::{JsString, Object, Uint8Array};
use wasm_bindgen::{JsCast, JsValue};
use wasm_bindgen_futures::JsFuture;

/// Per-file and total caps for directory snapshots: the free tier is a
/// view-only browser for content repos; packfiles can legitimately be a
/// few MB, but a huge repo can't ship over a network snapshot path.
pub const MAX_FILE_BYTES: u32 = 8 * 1024 * 1024;
pub const MAX_TOTAL_BYTES: u32 = 96 * 1024 * 1024;
pub const MAX_FILES: u32 = 8_000;

/// A snapshot of a repository directory: every file's bytes by
/// repo-root-relative, `/`-separated path (including everything under
/// `.git/`).
pub struct Snapshot {
    pub files: BTreeMap<String, Vec<u8>>,
    /// Files above the per-file cap (listed so the UI can say what's
    /// missing rather than silently dropping them).
    pub skipped: Vec<String>,
    /// True when the file-count cap cut the walk short.
    pub truncated: bool,
    /// Name of the chosen folder (browser gives the display name).
    pub name: String,
}

impl Snapshot {
    pub fn total_bytes(&self) -> usize {
        self.files.values().map(|v| v.len()).sum()
    }
}

const WALKER_JS: &str = r#"(() => {
  async function walk(dir, path, state) {
    for await (const [name, handle] of dir.entries()) {
      if (state.files.size > state.maxFiles) { state.truncated = true; return; }
      const p = path ? path + "/" + name : name;
      if (handle.kind === "file") {
        const file = await handle.getFile();
        if (file.size <= state.maxFile && state.total + file.size <= state.maxTotal) {
          state.files.set(p, new Uint8Array(await file.arrayBuffer()));
          state.total += file.size;
        } else {
          state.skipped.push(p);
        }
      } else if (handle.kind === "directory") {
        if (p === "node_modules") continue;
        await walk(handle, p, state);
      }
    }
  }
  return async (maxFile, maxTotal, maxFiles) => {
    if (typeof globalThis.showDirectoryPicker !== "function") {
      throw new Error("This browser can't open local folders. Try Chrome or Edge, or use the demo repository.");
    }
    const dir = await globalThis.showDirectoryPicker({ mode: "read" });
    const state = { files: new Map(), skipped: [], maxFile, maxTotal, maxFiles, total: 0, truncated: false };
    await walk(dir, "", state);
    return { name: dir.name, files: state.files, skipped: state.skipped, truncated: state.truncated };
  };
})()"#;

/// Opens the OS directory picker and snapshots the chosen folder.
pub async fn open_directory_snapshot() -> Result<Snapshot, JsValue> {
    let factory = js_sys::eval(WALKER_JS)?;
    let factory: js_sys::Function = factory
        .dyn_into()
        .map_err(|_| JsValue::from_str("walker factory is not a function"))?;
    let picked = factory.call3(
        &JsValue::UNDEFINED,
        &JsValue::from_f64(MAX_FILE_BYTES as f64),
        &JsValue::from_f64(MAX_TOTAL_BYTES as f64),
        &JsValue::from_f64(MAX_FILES as f64),
    )?;
    let promise = js_sys::Promise::resolve(&picked);
    let result = JsFuture::from(promise).await?;
    snapshot_from_js(&result)
}

/// Loads the embedded demo repository.
pub fn demo_snapshot() -> Result<Snapshot, JsValue> {
    const BIN: &[u8] = include_bytes!("demo_repo.bin");

    fn read(at: usize, n: usize) -> Vec<u8> {
        BIN[at..at + n].to_vec()
    }

    let mut files = BTreeMap::new();
    let mut cursor = 0usize;
    let count = u32::from_le_bytes(read(cursor, 4).try_into().unwrap()) as usize;
    cursor += 4;
    for _ in 0..count {
        let path_len = u32::from_le_bytes(read(cursor, 4).try_into().unwrap()) as usize;
        cursor += 4;
        let path = String::from_utf8(read(cursor, path_len))
            .map_err(|_| JsValue::from_str("demo repo: bad path"))?;
        cursor += path_len;
        let data_len = u64::from_le_bytes(read(cursor, 8).try_into().unwrap()) as usize;
        cursor += 8;
        let data = read(cursor, data_len);
        cursor += data_len;
        files.insert(path, data);
    }
    Ok(Snapshot {
        files,
        skipped: Vec::new(),
        truncated: false,
        name: "sunrise-bakery-website".into(),
    })
}

fn snapshot_from_js(value: &JsValue) -> Result<Snapshot, JsValue> {
    let obj: Object = value
        .dyn_ref::<Object>()
        .ok_or_else(|| JsValue::from_str("walker result is not an object"))?
        .to_owned();

    let name = js_sys::Reflect::get(&obj, &JsString::from("name"))?
        .dyn_into::<JsString>()
        .map(|s| s.into())
        .unwrap_or_else(|_| "repository".to_string());

    let files_js = js_sys::Reflect::get(&obj, &JsString::from("files"))?;
    let files_js: js_sys::Map = files_js
        .dyn_into()
        .map_err(|_| JsValue::from_str("files is not a Map"))?;

    let mut files = BTreeMap::new();
    for entry in files_js.entries() {
        let entry: js_sys::Array = entry
            .map_err(|_| JsValue::from_str("map iteration failed"))?
            .dyn_into()
            .map_err(|_| JsValue::from_str("map entry not an array"))?;
        let key: String = entry
            .get(0)
            .dyn_into::<JsString>()
            .map(|s| s.into())
            .map_err(|_| JsValue::from_str("map key not a string"))?;
        let bytes_js: Uint8Array = entry
            .get(1)
            .dyn_into()
            .map_err(|_| JsValue::from_str("map value not bytes"))?;
        files.insert(key, bytes_js.to_vec());
    }

    let skipped_js = js_sys::Reflect::get(&obj, &JsString::from("skipped"))?;
    let skipped_arr: js_sys::Array = skipped_js
        .dyn_into()
        .map_err(|_| JsValue::from_str("skipped is not an array"))?;
    let mut skipped = Vec::new();
    for item in skipped_arr.iter() {
        if let Ok(s) = item.dyn_into::<JsString>() {
            skipped.push(s.into());
        }
    }
    let truncated = js_sys::Reflect::get(&obj, &JsString::from("truncated"))?
        .is_truthy();

    Ok(Snapshot { files, skipped, truncated, name })
}
